#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Convert Egg Rescue Lua data tables to JSON for the C# PC runtime.

Usage:
  python MissingEggDoc-main/scripts/lua_to_json.py
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DATA = ROOT / "Assets" / "Data"
OUT = ROOT / "Assets" / "Resources" / "GameData"

STRING_RE = re.compile(r'"(?:\\.|[^"\\])*"')


class LuaParseError(RuntimeError):
    pass


class Lexer:
    def __init__(self, text: str) -> None:
        self.src = self._strip_comments(text)
        self.n = len(self.src)
        self.i = 0

    @staticmethod
    def _strip_comments(text: str) -> str:
        out = []
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch == "-" and i + 1 < n and text[i + 1] == "-":
                if i + 3 < n and text[i + 2] == "[" and text[i + 3] == "[":
                    end = text.find("]]", i + 4)
                    i = n if end < 0 else end + 2
                    continue
                while i < n and text[i] not in "\n\r":
                    i += 1
                continue
            if ch == '"':
                j = i + 1
                while j < n:
                    if text[j] == "\\" and j + 1 < n:
                        j += 2
                        continue
                    if text[j] == '"':
                        j += 1
                        break
                    j += 1
                out.append(text[i:j])
                i = j
                continue
            out.append(ch)
            i += 1
        return "".join(out)

    def peek(self) -> str:
        while self.i < self.n and self.src[self.i].isspace():
            self.i += 1
        return self.src[self.i] if self.i < self.n else ""

    def take(self, n: int = 1) -> str:
        self.peek()
        s = self.src[self.i : self.i + n]
        self.i += n
        return s

    def ident(self) -> str:
        self.peek()
        start = self.i
        if self.i < self.n and (self.src[self.i].isalpha() or self.src[self.i] == "_"):
            self.i += 1
            while self.i < self.n and (self.src[self.i].isalnum() or self.src[self.i] == "_"):
                self.i += 1
        return self.src[start : self.i]

    def number(self) -> float | int:
        self.peek()
        start = self.i
        if self.i < self.n and self.src[self.i] in "+-":
            self.i += 1
        while self.i < self.n and (self.src[self.i].isdigit() or self.src[self.i] in ".eE"):
            self.i += 1
        raw = self.src[start : self.i]
        if "." in raw or "e" in raw.lower():
            return float(raw)
        return int(raw)

    def string(self) -> str:
        self.peek()
        if self.take() != '"':
            raise LuaParseError("expected string")
        buf = []
        while self.i < self.n:
            ch = self.src[self.i]
            self.i += 1
            if ch == '"':
                break
            if ch == "\\" and self.i < self.n:
                nxt = self.src[self.i]
                self.i += 1
                escapes = {"n": "\n", "r": "\r", "t": "\t", '"': '"', "\\": "\\"}
                buf.append(escapes.get(nxt, nxt))
            else:
                buf.append(ch)
        return "".join(buf)


def parse_value(lex: Lexer):
    ch = lex.peek()
    if ch == "{":
        return parse_table(lex)
    if ch == '"':
        return lex.string()
    if ch in "+-" or ch.isdigit():
        return lex.number()
    ident = lex.ident()
    if ident == "true":
        return True
    if ident == "false":
        return False
    if ident == "nil":
        return None
    raise LuaParseError(f"unexpected ident {ident!r} at {lex.i}")


def parse_table(lex: Lexer):
    if lex.take() != "{":
        raise LuaParseError("expected {")
    obj: dict = {}
    arr: list = []
    is_array = True
    next_index = 1
    while True:
        ch = lex.peek()
        if ch == "}":
            lex.take()
            break
        if ch == "":
            raise LuaParseError("unterminated table")

        # [key] = value  or  ident = value  or  value
        key = None
        if ch == "[":
            lex.take()
            key = parse_value(lex)
            if lex.peek() != "]":
                raise LuaParseError("expected ]")
            lex.take()
            if lex.peek() != "=":
                raise LuaParseError("expected = after [] key")
            lex.take()
            val = parse_value(lex)
        else:
            # lookahead: ident =
            save = lex.i
            ident = lex.ident()
            if ident and lex.peek() == "=":
                lex.take()
                key = ident
                val = parse_value(lex)
            else:
                lex.i = save
                val = parse_value(lex)
                key = next_index
                next_index += 1

        if isinstance(key, int) and key == len(arr) + 1 and is_array:
            arr.append(val)
        else:
            is_array = False
            obj[str(key)] = val
            if isinstance(key, int) and key >= next_index:
                next_index = key + 1

        ch = lex.peek()
        if ch == ",":
            lex.take()
            continue
        if ch == "}":
            lex.take()
            break
        raise LuaParseError(f"expected , or }} at {lex.i}, got {ch!r}")

    if obj and arr:
        for i, v in enumerate(arr, start=1):
            obj.setdefault(str(i), v)
        return obj
    if obj:
        return obj
    return arr


def extract_assignment(text: str, name: str):
    m = re.search(rf"{re.escape(name)}\s*=", text)
    if not m:
        raise LuaParseError(f"{name} assignment not found")
    lex = Lexer(text[m.end() :])
    return parse_value(lex)


def dialogue_config_to_nodes(table) -> list[dict]:
    nodes = []
    if isinstance(table, list):
        for i, node in enumerate(table, start=1):
            if isinstance(node, dict):
                item = dict(node)
                item["id"] = i
                nodes.append(item)
        return nodes
    if not isinstance(table, dict):
        return nodes
    for key, node in table.items():
        if not isinstance(node, dict):
            continue
        try:
            nid = int(key)
        except (TypeError, ValueError):
            continue
        item = dict(node)
        item["id"] = nid
        nodes.append(item)
    nodes.sort(key=lambda n: n["id"])
    return nodes


def convert_global_variables() -> None:
    src = DATA / "GlobalData" / "GlobalVariables.lua"
    table = extract_assignment(src.read_text(encoding="utf-8"), "GlobalVariables")
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "global_variables.json").write_text(
        json.dumps(table, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    print(f"wrote global_variables.json ({len(table)} vars)")


def convert_npc_data() -> None:
    src = DATA / "GlobalData" / "NPCData_Config.lua"
    table = extract_assignment(src.read_text(encoding="utf-8"), "NPCData")
    (OUT / "npc_data.json").write_text(
        json.dumps(table, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    n = len(table.get("npcList", [])) if isinstance(table, dict) else 0
    print(f"wrote npc_data.json ({n} npcs)")


def convert_dialogue_file(path: Path, out_name: str) -> None:
    text = path.read_text(encoding="utf-8")
    table = extract_assignment(text, "DialogueConfig")
    nodes = dialogue_config_to_nodes(table)
    dest_dir = OUT / "Dialogue"
    dest_dir.mkdir(parents=True, exist_ok=True)
    (dest_dir / f"{out_name}.json").write_text(
        json.dumps({"module": out_name, "nodes": nodes}, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    print(f"wrote Dialogue/{out_name}.json ({len(nodes)} nodes)")


def main() -> int:
    convert_global_variables()
    convert_npc_data()
    convert_dialogue_file(DATA / "DialogueData" / "miaosu.lua", "miaosu")
    from_doc = DATA / "DialogueData" / "FROM_DOC"
    for path in sorted(from_doc.glob("*_FROM_DOC.lua")):
        convert_dialogue_file(path, path.stem)
    return 0


if __name__ == "__main__":
    sys.exit(main())

using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

static class Program
{
    static int Main(string[] args)
    {
        var root = FindRepoRoot();
        var data = Path.Combine(root, "Assets", "Data");
        var output = Path.Combine(root, "Assets", "Resources", "GameData");
        Directory.CreateDirectory(output);
        Directory.CreateDirectory(Path.Combine(output, "Dialogue"));

        ConvertAssignment(Path.Combine(data, "GlobalData", "GlobalVariables.lua"), "GlobalVariables",
            Path.Combine(output, "global_variables.json"));
        ConvertAssignment(Path.Combine(data, "GlobalData", "NPCData_Config.lua"), "NPCData",
            Path.Combine(output, "npc_data.json"));

        ConvertDialogue(Path.Combine(data, "DialogueData", "miaosu.lua"), "miaosu", output);
        foreach (var path in Directory.GetFiles(Path.Combine(data, "DialogueData", "FROM_DOC"), "*_FROM_DOC.lua"))
            ConvertDialogue(path, Path.GetFileNameWithoutExtension(path), output);

        Console.WriteLine("done");
        return 0;
    }

    static string FindRepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir != null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "Assets", "Data", "GlobalData", "GlobalVariables.lua")))
                return dir.FullName;
            dir = dir.Parent;
        }

        var cwd = Directory.GetCurrentDirectory();
        if (File.Exists(Path.Combine(cwd, "Assets", "Data", "GlobalData", "GlobalVariables.lua")))
            return cwd;
        throw new DirectoryNotFoundException("Could not find repo root");
    }

    static void ConvertAssignment(string luaPath, string name, string jsonPath)
    {
        var node = LuaTableParser.ExtractAssignment(File.ReadAllText(luaPath), name);
        WriteJson(jsonPath, node);
        Console.WriteLine("wrote " + Path.GetFileName(jsonPath));
    }

    static void ConvertDialogue(string luaPath, string module, string outputRoot)
    {
        var table = LuaTableParser.ExtractAssignment(File.ReadAllText(luaPath), "DialogueConfig");
        var nodes = new JsonArray();
        if (table is JsonObject obj)
        {
            var ordered = obj
                .Where(kv => int.TryParse(kv.Key, out _))
                .Select(kv => (Id: int.Parse(kv.Key), Node: kv.Value as JsonObject))
                .Where(x => x.Node != null)
                .OrderBy(x => x.Id);
            foreach (var (id, node) in ordered)
            {
                node!["id"] = id;
                nodes.Add(node);
            }
        }
        else if (table is JsonArray arr)
        {
            for (var i = 0; i < arr.Count; i++)
            {
                if (arr[i] is JsonObject node)
                {
                    node["id"] = i + 1;
                    nodes.Add(node);
                }
            }
        }

        var wrapped = new JsonObject
        {
            ["module"] = module,
            ["nodes"] = nodes
        };
        var dest = Path.Combine(outputRoot, "Dialogue", module + ".json");
        WriteJson(dest, wrapped);
        Console.WriteLine($"wrote Dialogue/{module}.json ({nodes.Count} nodes)");
    }

    static void WriteJson(string path, JsonNode? node)
    {
        var json = node?.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) ?? "null";
        File.WriteAllText(path, json, new UTF8Encoding(false));
    }
}

static class LuaTableParser
{
    public static JsonNode? ExtractAssignment(string text, string name)
    {
        var stripped = StripComments(text);
        var token = name + " =";
        var idx = stripped.IndexOf(token, StringComparison.Ordinal);
        if (idx < 0)
        {
            token = name + "=";
            idx = stripped.IndexOf(token, StringComparison.Ordinal);
        }
        if (idx < 0)
            throw new InvalidOperationException(name + " assignment not found");
        var lex = new Lexer(stripped[(idx + token.Length)..]);
        return ParseValue(lex);
    }

    static string StripComments(string text)
    {
        var sb = new StringBuilder(text.Length);
        var i = 0;
        while (i < text.Length)
        {
            if (i + 1 < text.Length && text[i] == '-' && text[i + 1] == '-')
            {
                if (i + 3 < text.Length && text[i + 2] == '[' && text[i + 3] == '[')
                {
                    var end = text.IndexOf("]]", i + 4, StringComparison.Ordinal);
                    i = end < 0 ? text.Length : end + 2;
                    continue;
                }
                while (i < text.Length && text[i] != '\n' && text[i] != '\r')
                    i++;
                continue;
            }
            if (text[i] == '"')
            {
                sb.Append(text[i++]);
                while (i < text.Length)
                {
                    var ch = text[i++];
                    sb.Append(ch);
                    if (ch == '\\' && i < text.Length)
                    {
                        sb.Append(text[i++]);
                        continue;
                    }
                    if (ch == '"')
                        break;
                }
                continue;
            }
            sb.Append(text[i++]);
        }
        return sb.ToString();
    }

    sealed class Lexer
    {
        public readonly string Src;
        public int I;
        public Lexer(string src) { Src = src; }

        public char Peek()
        {
            SkipWs();
            return I < Src.Length ? Src[I] : '\0';
        }

        public char Take()
        {
            SkipWs();
            return I < Src.Length ? Src[I++] : '\0';
        }

        public void SkipWs()
        {
            while (I < Src.Length && char.IsWhiteSpace(Src[I]))
                I++;
        }

        public string Ident()
        {
            SkipWs();
            var start = I;
            if (I < Src.Length && (char.IsLetter(Src[I]) || Src[I] == '_'))
            {
                I++;
                while (I < Src.Length && (char.IsLetterOrDigit(Src[I]) || Src[I] == '_'))
                    I++;
            }
            return Src[start..I];
        }

        public JsonNode Number()
        {
            SkipWs();
            var start = I;
            if (I < Src.Length && (Src[I] == '+' || Src[I] == '-'))
                I++;
            while (I < Src.Length && (char.IsDigit(Src[I]) || Src[I] is '.' or 'e' or 'E' or '+' or '-'))
            {
                if ((Src[I] == '+' || Src[I] == '-') && I > start && Src[I - 1] is not ('e' or 'E'))
                    break;
                I++;
            }
            var raw = Src[start..I];
            if (raw.Contains('.') || raw.Contains('e') || raw.Contains('E'))
                return JsonValue.Create(double.Parse(raw, CultureInfo.InvariantCulture));
            return JsonValue.Create(long.Parse(raw, CultureInfo.InvariantCulture));
        }

        public string String()
        {
            SkipWs();
            if (Take() != '"')
                throw new InvalidOperationException("expected string");
            var sb = new StringBuilder();
            while (I < Src.Length)
            {
                var ch = Src[I++];
                if (ch == '"')
                    break;
                if (ch == '\\' && I < Src.Length)
                {
                    var nxt = Src[I++];
                    sb.Append(nxt switch
                    {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '"' => '"',
                        '\\' => '\\',
                        _ => nxt
                    });
                }
                else
                    sb.Append(ch);
            }
            return sb.ToString();
        }
    }

    static JsonNode? ParseValue(Lexer lex)
    {
        var ch = lex.Peek();
        if (ch == '{')
            return ParseTable(lex);
        if (ch == '"')
            return JsonValue.Create(lex.String());
        if (ch is '+' or '-' || char.IsDigit(ch))
            return lex.Number();
        var ident = lex.Ident();
        return ident switch
        {
            "true" => JsonValue.Create(true),
            "false" => JsonValue.Create(false),
            "nil" => null,
            _ => throw new InvalidOperationException($"unexpected ident {ident} at {lex.I}")
        };
    }

    static JsonNode ParseTable(Lexer lex)
    {
        if (lex.Take() != '{')
            throw new InvalidOperationException("expected {");
        var obj = new JsonObject();
        var arr = new JsonArray();
        var isArray = true;
        var nextIndex = 1L;
        while (true)
        {
            var ch = lex.Peek();
            if (ch == '}')
            {
                lex.Take();
                break;
            }
            if (ch == '\0')
                throw new InvalidOperationException("unterminated table");

            JsonNode? keyNode = null;
            JsonNode? val;
            if (ch == '[')
            {
                lex.Take();
                keyNode = ParseValue(lex);
                if (lex.Peek() != ']')
                    throw new InvalidOperationException("expected ]");
                lex.Take();
                if (lex.Peek() != '=')
                    throw new InvalidOperationException("expected = after [] key");
                lex.Take();
                val = ParseValue(lex);
            }
            else
            {
                var save = lex.I;
                var ident = lex.Ident();
                if (!string.IsNullOrEmpty(ident) && lex.Peek() == '=')
                {
                    lex.Take();
                    keyNode = JsonValue.Create(ident);
                    val = ParseValue(lex);
                }
                else
                {
                    lex.I = save;
                    val = ParseValue(lex);
                    keyNode = JsonValue.Create(nextIndex);
                    nextIndex++;
                }
            }

            long? intKey = null;
            if (keyNode is JsonValue kv)
            {
                if (kv.TryGetValue<long>(out var l))
                    intKey = l;
                else if (kv.TryGetValue<string>(out var s) && long.TryParse(s, out var parsed))
                    intKey = parsed;
            }

            if (intKey is long ik && isArray && ik == arr.Count + 1)
            {
                arr.Add(val);
            }
            else
            {
                isArray = false;
                var key = intKey?.ToString(CultureInfo.InvariantCulture)
                          ?? keyNode?.GetValue<string>()
                          ?? keyNode?.ToJsonString()
                          ?? nextIndex.ToString(CultureInfo.InvariantCulture);
                obj[key] = val?.DeepClone();
            }

            ch = lex.Peek();
            if (ch == ',')
            {
                lex.Take();
                continue;
            }
            if (ch == '}')
            {
                lex.Take();
                break;
            }
            throw new InvalidOperationException($"expected , or }} at {lex.I}, got {ch}");
        }

        if (obj.Count > 0 && arr.Count > 0)
        {
            for (var i = 0; i < arr.Count; i++)
            {
                var k = (i + 1).ToString(CultureInfo.InvariantCulture);
                if (!obj.ContainsKey(k))
                    obj[k] = arr[i]?.DeepClone();
            }
            return obj;
        }
        if (obj.Count > 0)
            return obj;
        return arr;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace EggRescue
{
    public sealed class JsonValue
    {
        public enum Kind
        {
            Null,
            Bool,
            Number,
            String,
            Array,
            Object
        }

        public Kind Type { get; private set; }
        public bool BoolValue;
        public double NumberValue;
        public string StringValue;
        public List<JsonValue> ArrayValue;
        public Dictionary<string, JsonValue> ObjectValue;

        public static JsonValue Null = new JsonValue { Type = Kind.Null };
        public static JsonValue Parse(string json)
        {
            return new Parser(json ?? "null").ParseValue();
        }

        public bool IsNull { get { return Type == Kind.Null; } }

        public JsonValue this[string key]
        {
            get
            {
                JsonValue value;
                if (Type == Kind.Object && ObjectValue != null && ObjectValue.TryGetValue(key, out value))
                    return value;
                return Null;
            }
        }

        public JsonValue this[int index]
        {
            get
            {
                if (Type == Kind.Array && ArrayValue != null && index >= 0 && index < ArrayValue.Count)
                    return ArrayValue[index];
                return Null;
            }
        }

        public int Count
        {
            get
            {
                if (Type == Kind.Array && ArrayValue != null) return ArrayValue.Count;
                if (Type == Kind.Object && ObjectValue != null) return ObjectValue.Count;
                return 0;
            }
        }

        public string AsString(string fallback = "")
        {
            if (Type == Kind.String) return StringValue ?? fallback;
            if (Type == Kind.Number) return NumberValue.ToString(CultureInfo.InvariantCulture);
            if (Type == Kind.Bool) return BoolValue ? "true" : "false";
            return fallback;
        }

        public int AsInt(int fallback = 0)
        {
            if (Type == Kind.Number) return (int)NumberValue;
            if (Type == Kind.String)
            {
                int n;
                if (int.TryParse(StringValue, NumberStyles.Integer, CultureInfo.InvariantCulture, out n))
                    return n;
            }
            if (Type == Kind.Bool) return BoolValue ? 1 : 0;
            return fallback;
        }

        public bool AsBool(bool fallback = false)
        {
            if (Type == Kind.Bool) return BoolValue;
            if (Type == Kind.Number) return NumberValue != 0;
            if (Type == Kind.String)
            {
                if (StringValue == "true" || StringValue == "1") return true;
                if (StringValue == "false" || StringValue == "0") return false;
            }
            return fallback;
        }

        public bool Has(string key)
        {
            return Type == Kind.Object && ObjectValue != null && ObjectValue.ContainsKey(key) && !ObjectValue[key].IsNull;
        }

        public IEnumerable<JsonValue> AsArray()
        {
            if (Type == Kind.Array && ArrayValue != null)
                return ArrayValue;
            if (Type == Kind.Object && ObjectValue != null)
            {
                var list = new List<JsonValue>();
                var i = 1;
                JsonValue item;
                while (ObjectValue.TryGetValue(i.ToString(CultureInfo.InvariantCulture), out item))
                {
                    list.Add(item);
                    i++;
                }
                if (list.Count > 0)
                    return list;
            }
            return Array.Empty<JsonValue>();
        }

        sealed class Parser
        {
            readonly string _src;
            int _i;

            public Parser(string src) { _src = src; }

            public JsonValue ParseValue()
            {
                Skip();
                if (_i >= _src.Length) return Null;
                var ch = _src[_i];
                if (ch == '{') return ParseObject();
                if (ch == '[') return ParseArray();
                if (ch == '"') return OfString(ParseString());
                if (ch == 't' || ch == 'f') return OfBool(ParseLiteralBool());
                if (ch == 'n') { ParseNull(); return Null; }
                return OfNumber(ParseNumber());
            }

            JsonValue ParseObject()
            {
                _i++;
                var obj = new Dictionary<string, JsonValue>();
                Skip();
                if (Peek() == '}') { _i++; return OfObject(obj); }
                while (true)
                {
                    Skip();
                    var key = ParseString();
                    Skip();
                    Expect(':');
                    var val = ParseValue();
                    obj[key] = val;
                    Skip();
                    if (Peek() == ',') { _i++; continue; }
                    Expect('}');
                    break;
                }
                return OfObject(obj);
            }

            JsonValue ParseArray()
            {
                _i++;
                var arr = new List<JsonValue>();
                Skip();
                if (Peek() == ']') { _i++; return OfArray(arr); }
                while (true)
                {
                    arr.Add(ParseValue());
                    Skip();
                    if (Peek() == ',') { _i++; continue; }
                    Expect(']');
                    break;
                }
                return OfArray(arr);
            }

            string ParseString()
            {
                Expect('"');
                var sb = new StringBuilder();
                while (_i < _src.Length)
                {
                    var ch = _src[_i++];
                    if (ch == '"') break;
                    if (ch == '\\' && _i < _src.Length)
                    {
                        var nxt = _src[_i++];
                        switch (nxt)
                        {
                            case 'n': sb.Append('\n'); break;
                            case 'r': sb.Append('\r'); break;
                            case 't': sb.Append('\t'); break;
                            case '"': sb.Append('"'); break;
                            case '\\': sb.Append('\\'); break;
                            case 'u':
                                if (_i + 4 <= _src.Length)
                                {
                                    var hex = _src.Substring(_i, 4);
                                    _i += 4;
                                    int code;
                                    if (int.TryParse(hex, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out code))
                                        sb.Append((char)code);
                                }
                                break;
                            default: sb.Append(nxt); break;
                        }
                    }
                    else sb.Append(ch);
                }
                return sb.ToString();
            }

            double ParseNumber()
            {
                var start = _i;
                if (Peek() == '-' || Peek() == '+') _i++;
                while (_i < _src.Length && (char.IsDigit(_src[_i]) || _src[_i] == '.' || _src[_i] == 'e' || _src[_i] == 'E' || _src[_i] == '+' || _src[_i] == '-'))
                {
                    if ((_src[_i] == '+' || _src[_i] == '-') && _i > start && _src[_i - 1] != 'e' && _src[_i - 1] != 'E')
                        break;
