using System;
using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public enum VarType
    {
        Bool,
        Int
    }

    public sealed class VarRecord
    {
        public VarType Type;
        public int IntValue;
        public bool BoolValue;

        public object Boxed
        {
            get { return Type == VarType.Bool ? (object)BoolValue : IntValue; }
        }
    }

    public static class GameState
    {
        static readonly Dictionary<string, VarRecord> Vars = new Dictionary<string, VarRecord>();
        static readonly Dictionary<string, bool> BranchFlags = new Dictionary<string, bool>();
        static bool _dispatching;

        public static IReadOnlyDictionary<string, VarRecord> All { get { return Vars; } }

        public static void LoadDefaults()
        {
            Vars.Clear();
            BranchFlags.Clear();
            var ta = Resources.Load<TextAsset>("GameData/global_variables");
            if (ta == null)
            {
                Debug.LogError("[GameState] missing Resources/GameData/global_variables.json");
                return;
            }

            var root = JsonValue.Parse(ta.text);
            foreach (var item in root.AsArray())
            {
                var name = item["name"].AsString();
                if (string.IsNullOrEmpty(name)) continue;
                var typeName = item["type"].AsString("bool");
                var rec = new VarRecord();
                if (typeName == "int")
                {
                    rec.Type = VarType.Int;
                    rec.IntValue = item["value"].AsInt();
                }
                else
                {
                    rec.Type = VarType.Bool;
                    rec.BoolValue = item["value"].AsBool();
                }
                Vars[name] = rec;
            }
            Debug.Log("[GameState] loaded " + Vars.Count + " variables");
        }

        public static void ResetToDefaults()
        {
            LoadDefaults();
            NpcRegistry.ResetBranchesToStart();
        }

        public static object Get(string name)
        {
            VarRecord rec;
            if (string.IsNullOrEmpty(name) || !Vars.TryGetValue(name, out rec))
                return null;
            return rec.Boxed;
        }

        public static bool GetBool(string name, bool fallback = false)
        {
            VarRecord rec;
            if (string.IsNullOrEmpty(name) || !Vars.TryGetValue(name, out rec))
                return fallback;
            if (rec.Type == VarType.Bool) return rec.BoolValue;
            return rec.IntValue != 0;
        }

        public static int GetInt(string name, int fallback = 0)
        {
            VarRecord rec;
            if (string.IsNullOrEmpty(name) || !Vars.TryGetValue(name, out rec))
                return fallback;
            if (rec.Type == VarType.Int) return rec.IntValue;
            return rec.BoolValue ? 1 : 0;
        }

        public static VarType GetVarType(string name)
        {
            VarRecord rec;
            if (Vars.TryGetValue(name, out rec))
                return rec.Type;
            return VarType.Bool;
        }

        public static bool Has(string name)
        {
            return !string.IsNullOrEmpty(name) && Vars.ContainsKey(name);
        }

        public static void Set(string name, object value, string typeHint = null)
        {
            if (string.IsNullOrEmpty(name)) return;
            VarRecord rec;
            if (!Vars.TryGetValue(name, out rec))
            {
                rec = new VarRecord();
                rec.Type = typeHint == "int" ? VarType.Int : VarType.Bool;
                Vars[name] = rec;
            }

            if (rec.Type == VarType.Bool)
                rec.BoolValue = ToBool(value);
            else
                rec.IntValue = ToInt(value);

            DispatchSideEffects(name, rec);
        }

        public static void SetBool(string name, bool value)
        {
            Set(name, value, "bool");
        }

        public static void SetInt(string name, int value)
        {
            Set(name, value, "int");
        }

        public static void SaveBranchFlag(string flag)
        {
            if (string.IsNullOrEmpty(flag)) return;
            BranchFlags[flag] = true;
        }

        public static bool CheckBranchFlag(string flag)
        {
            bool v;
            return !string.IsNullOrEmpty(flag) && BranchFlags.TryGetValue(flag, out v) && v;
        }

        public static Dictionary<string, object> CaptureSave()
        {
            var dict = new Dictionary<string, object>();
            foreach (var kv in Vars)
                dict[kv.Key] = kv.Value.Boxed;
            foreach (var kv in BranchFlags)
                dict["Branch_" + kv.Key] = kv.Value;
            return dict;
        }

        public static void RestoreSave(Dictionary<string, JsonValue> data)
        {
            if (data == null) return;
            foreach (var kv in data)
            {
                if (kv.Key.StartsWith("Branch_", StringComparison.Ordinal))
                {
                    BranchFlags[kv.Key.Substring("Branch_".Length)] = kv.Value.AsBool();
                    continue;
                }
                VarRecord rec;
                if (!Vars.TryGetValue(kv.Key, out rec)) continue;
                if (rec.Type == VarType.Bool) rec.BoolValue = kv.Value.AsBool();
                else rec.IntValue = kv.Value.AsInt();
            }
        }

        static bool ToBool(object value)
        {
            if (value is bool) return (bool)value;
            if (value is int) return (int)value != 0;
            if (value is string)
            {
                var s = (string)value;
                return s == "true" || s == "1";
            }
            return false;
        }

        static int ToInt(object value)
        {
            if (value is int) return (int)value;
            if (value is bool) return (bool)value ? 1 : 0;
            if (value is string)
            {
                int n;
                if (int.TryParse((string)value, out n)) return n;
            }
            if (value is double) return (int)(double)value;
            if (value is float) return (int)(float)value;
            return 0;
        }

        static void DispatchSideEffects(string name, VarRecord rec)
        {
            if (_dispatching) return;
            _dispatching = true;
            try
            {
                GameEvents.RaiseVariableChanged(name);
                if (name == "CheeseCount" && rec.Type == VarType.Int)
                    GameEvents.RaiseCheeseCountChanged();
                if (name != null && name.StartsWith("Mouse_", StringComparison.Ordinal))
                    GameEvents.RaiseMouseFlagsNeedRefresh();
                if (name == "NGPlus" && rec.Type == VarType.Bool && rec.BoolValue)
                    GameEvents.RaiseNGPlusActivated();
                if (name == "BlackCat_Entered")
                    GameEvents.RaiseBlackCatEntered();
                if (name == "E05_GrainSoakGet")
                    GameEvents.RaiseE05GrainSoakGot();
            }
            finally
            {
                _dispatching = false;
            }
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public sealed class NpcStoryGraph
    {
        public int BranchId;
        public string ModuleName;
        public string Description;
        public List<string> MergeModules;
    }

    public sealed class NpcDef
    {
        public string Id;
        public string Name;
        public string AvatarPath;
        public int CurrentBranchId = 1;
        public readonly List<NpcStoryGraph> StoryGraphs = new List<NpcStoryGraph>();
    }

    public static class NpcRegistry
    {
        static readonly List<NpcDef> List = new List<NpcDef>();
        static readonly Dictionary<string, NpcDef> ByName = new Dictionary<string, NpcDef>();
        static readonly Dictionary<string, NpcDef> ById = new Dictionary<string, NpcDef>();

        public static IReadOnlyList<NpcDef> All { get { return List; } }

        public static void Load()
        {
            List.Clear();
            ByName.Clear();
            ById.Clear();
            var ta = Resources.Load<TextAsset>("GameData/npc_data");
            if (ta == null)
            {
                Debug.LogError("[NpcRegistry] missing Resources/GameData/npc_data.json");
                return;
            }

            var root = JsonValue.Parse(ta.text);
            foreach (var item in root["npcList"].AsArray())
            {
                var npc = new NpcDef
                {
                    Id = item["id"].AsString(),
                    Name = item["name"].AsString(),
                    AvatarPath = item["avatarPath"].AsString(),
                    CurrentBranchId = item["currentBranchId"].AsInt(1)
                };
                foreach (var g in item["storyGraphs"].AsArray())
                {
                    var graph = new NpcStoryGraph
                    {
                        BranchId = g["branchId"].AsInt(1),
                        ModuleName = g["luaModuleName"].AsString(),
                        Description = g["storyDescription"].AsString(),
                        MergeModules = new List<string>()
                    };
                    if (string.IsNullOrEmpty(graph.ModuleName))
                    {
                        var path = g["luaAssetPath"].AsString();
                        graph.ModuleName = System.IO.Path.GetFileNameWithoutExtension(path);
                    }
                    foreach (var extra in g["mergeLuaModules"].AsArray())
                        graph.MergeModules.Add(extra.AsString());
                    npc.StoryGraphs.Add(graph);
                }
                List.Add(npc);
                if (!string.IsNullOrEmpty(npc.Name)) ByName[npc.Name] = npc;
                if (!string.IsNullOrEmpty(npc.Id)) ById[npc.Id] = npc;
            }
            ResetBranchesToStart();
            Debug.Log("[NpcRegistry] loaded " + List.Count + " npcs");
        }

        public static NpcDef GetByName(string name)
        {
            NpcDef npc;
            if (!string.IsNullOrEmpty(name) && ByName.TryGetValue(name, out npc))
                return npc;
            return null;
        }

        public static void UnlockBranch(string npcName, int branchId)
        {
            var npc = GetByName(npcName);
            if (npc == null || branchId <= 0) return;
            npc.CurrentBranchId = branchId;
        }

        public static void ResetBranchesToStart()
        {
            for (var i = 0; i < List.Count; i++)
                List[i].CurrentBranchId = 1;
        }

        public static string ResolveModuleName(NpcDef npc)
        {
            if (npc == null || npc.StoryGraphs.Count == 0) return null;
            for (var i = 0; i < npc.StoryGraphs.Count; i++)
            {
                if (npc.StoryGraphs[i].BranchId == npc.CurrentBranchId && !string.IsNullOrEmpty(npc.StoryGraphs[i].ModuleName))
                    return npc.StoryGraphs[i].ModuleName;
            }
            for (var i = 0; i < npc.StoryGraphs.Count; i++)
            {
                if (npc.StoryGraphs[i].BranchId == 1 && !string.IsNullOrEmpty(npc.StoryGraphs[i].ModuleName))
                {
                    npc.CurrentBranchId = 1;
                    return npc.StoryGraphs[i].ModuleName;
                }
            }
            npc.CurrentBranchId = npc.StoryGraphs[0].BranchId;
            return npc.StoryGraphs[0].ModuleName;
        }

        public static NpcStoryGraph ResolveGraph(NpcDef npc)
        {
            if (npc == null) return null;
            var module = ResolveModuleName(npc);
            for (var i = 0; i < npc.StoryGraphs.Count; i++)
            {
                if (npc.StoryGraphs[i].ModuleName == module)
                    return npc.StoryGraphs[i];
            }
            return null;
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEngine;

namespace EggRescue
{
    public static class SaveService
    {
        const string FileName = "windmill_farm_save.json";

        public static string Path
        {
            get { return System.IO.Path.Combine(Application.persistentDataPath, FileName); }
        }

        public static void Save()
        {
            var sb = new StringBuilder();
            sb.Append("{\n");
            sb.Append("  \"variables\": {\n");
            var first = true;
            foreach (var kv in GameState.All)
            {
                if (!first) sb.Append(",\n");
                first = false;
                sb.Append("    \"").Append(Escape(kv.Key)).Append("\": ");
                if (kv.Value.Type == VarType.Bool)
                    sb.Append(kv.Value.BoolValue ? "true" : "false");
                else
                    sb.Append(kv.Value.IntValue.ToString());
            }
            sb.Append("\n  },\n");
            sb.Append("  \"npcBranches\": {\n");
            first = true;
            foreach (var npc in NpcRegistry.All)
            {
                if (!first) sb.Append(",\n");
                first = false;
                sb.Append("    \"").Append(Escape(npc.Name)).Append("\": ").Append(npc.CurrentBranchId);
            }
            sb.Append("\n  },\n");
            sb.Append("  \"cheesePicked\": [");
            first = true;
            foreach (var id in CheeseRegistry.PickedIds)
            {
                if (!first) sb.Append(", ");
                first = false;
                sb.Append("\"").Append(Escape(id)).Append("\"");
            }
            sb.Append("],\n");
            sb.Append("  \"discoveredPoints\": [");
            first = true;
            foreach (var id in InteractionPointVfx.DiscoveredIds)
            {
                if (!first) sb.Append(", ");
                first = false;
                sb.Append("\"").Append(Escape(id)).Append("\"");
            }
            sb.Append("]\n}\n");
            File.WriteAllText(Path, sb.ToString(), Encoding.UTF8);
            Debug.Log("[SaveService] saved " + Path);
        }

        public static bool Load()
        {
            if (!File.Exists(Path)) return false;
            var json = JsonValue.Parse(File.ReadAllText(Path, Encoding.UTF8));
            var vars = json["variables"];
            if (vars.Type == JsonValue.Kind.Object && vars.ObjectValue != null)
            {
                foreach (var kv in vars.ObjectValue)
                {
                    if (GameState.GetVarType(kv.Key) == VarType.Int)
                        GameState.SetInt(kv.Key, kv.Value.AsInt());
                    else
                        GameState.SetBool(kv.Key, kv.Value.AsBool());
                }
            }
            var branches = json["npcBranches"];
            if (branches.Type == JsonValue.Kind.Object && branches.ObjectValue != null)
            {
                foreach (var kv in branches.ObjectValue)
                    NpcRegistry.UnlockBranch(kv.Key, kv.Value.AsInt(1));
            }
            CheeseRegistry.ClearPicked();
            foreach (var id in json["cheesePicked"].AsArray())
                CheeseRegistry.MarkPicked(id.AsString());
            InteractionPointVfx.ClearDiscovered();
            foreach (var id in json["discoveredPoints"].AsArray())
                InteractionPointVfx.MarkDiscovered(id.AsString());
            Debug.Log("[SaveService] loaded " + Path);
            return true;
        }

        static string Escape(string s)
        {
            return (s ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"");
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public sealed class AudioDirector : MonoBehaviour
    {
        public static AudioDirector Instance { get; private set; }

        [SerializeField] AudioClip[] audioClips;
        [SerializeField] AudioSource sfxSource;
        [SerializeField] AudioSource bgmSource;
        [SerializeField] ParticleSystem[] particleSystems;

        AudioClip _originalBgm;
        readonly Dictionary<string, AudioClip> _byName = new Dictionary<string, AudioClip>();

        void Awake()
        {
            Instance = this;
            if (sfxSource == null) sfxSource = gameObject.AddComponent<AudioSource>();
            if (bgmSource == null)
            {
                bgmSource = gameObject.AddComponent<AudioSource>();
                bgmSource.loop = true;
                bgmSource.playOnAwake = false;
            }
            RebuildMap();
            LoadEditorClipsIfNeeded();
            if (bgmSource.clip != null) _originalBgm = bgmSource.clip;
        }

        void Start()
        {
            if (_byName.ContainsKey("audio_bgm"))
                PlayBGM();
            else if (_byName.ContainsKey("bgm"))
            {
                bgmSource.clip = _byName["bgm"];
                bgmSource.loop = true;
                bgmSource.Play();
                _originalBgm = bgmSource.clip;
            }
        }

        public void SetClips(AudioClip[] clips)
        {
            audioClips = clips;
            RebuildMap();
        }

        public void SetParticles(ParticleSystem[] systems)
        {
            particleSystems = systems;
        }

        void RebuildMap()
        {
            _byName.Clear();
            if (audioClips == null) return;
            for (var i = 0; i < audioClips.Length; i++)
            {
                var clip = audioClips[i];
                if (clip != null && !_byName.ContainsKey(clip.name))
                    _byName[clip.name] = clip;
            }
        }

        void LoadEditorClipsIfNeeded()
        {
            if (_byName.Count > 0) return;
#if UNITY_EDITOR
            var guids = UnityEditor.AssetDatabase.FindAssets("t:AudioClip", new[] { "Assets/Res/AudioAssets" });
            var list = new List<AudioClip>();
            for (var i = 0; i < (guids == null ? 0 : guids.Length); i++)
            {
                var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guids[i]);
                var clip = UnityEditor.AssetDatabase.LoadAssetAtPath<AudioClip>(path);
                if (clip != null) list.Add(clip);
            }
            audioClips = list.ToArray();
            RebuildMap();
#endif
        }

        public static void PlayAudio(string name)
        {
            if (Instance != null) Instance.PlayOneShot(name);
        }

        public static void PlayBGM()
        {
            if (Instance == null) return;
            if (Instance._originalBgm != null)
                Instance.bgmSource.clip = Instance._originalBgm;
            else
            {
                AudioClip clip;
                if (Instance._byName.TryGetValue("audio_bgm", out clip) || Instance._byName.TryGetValue("bgm", out clip))
                    Instance.bgmSource.clip = clip;
            }
            Instance.bgmSource.loop = true;
            if (Instance.bgmSource.clip != null)
                Instance.bgmSource.Play();
        }

        public static void StopBGM()
        {
            if (Instance != null && Instance.bgmSource != null)
                Instance.bgmSource.Stop();
        }

        public static void PlayMusic(string name)
        {
            if (Instance == null) return;
            AudioClip clip;
            if (!Instance._byName.TryGetValue(name ?? "", out clip) || clip == null)
            {
                Debug.Log("[AudioDirector] missing music " + name);
                return;
            }
            Instance.bgmSource.Stop();
            Instance.bgmSource.clip = clip;
            Instance.bgmSource.loop = true;
            Instance.bgmSource.Play();
        }

        public static float GetClipLength(string name)
        {
            if (Instance == null) return 0f;
            AudioClip clip;
            if (!Instance._byName.TryGetValue(name ?? "", out clip) || clip == null) return 0f;
            return clip.length;
        }

        public static void PlayParticle(string name, Vector3 position)
        {
            if (Instance == null || Instance.particleSystems == null) return;
            for (var i = 0; i < Instance.particleSystems.Length; i++)
            {
                var ps = Instance.particleSystems[i];
                if (ps == null || ps.name != name) continue;
                ps.transform.position = position;
                ps.Stop();
                ps.Clear();
                ps.Play();
                return;
            }
        }

        void PlayOneShot(string name)
        {
            AudioClip clip;
            if (!_byName.TryGetValue(name ?? "", out clip) || clip == null)
            {
                Debug.Log("[AudioDirector] missing clip " + name);
                return;
            }
            sfxSource.PlayOneShot(clip);
        }
    }
}

