        }
    }
    else if (table is JsonArray arr)
    {
        for (var i = 0; i < arr.Count; i++)
        {
            if (arr[i] is JsonObject node)
            {
                node["id"] = i + 1;
                nodes.Add(node);
            }
        }
    }

    var wrapped = new JsonObject
    {
        ["module"] = module,
        ["nodes"] = nodes
    };
    var dest = Path.Combine(outputRoot, "Dialogue", module + ".json");
    WriteJson(dest, wrapped);
    Console.WriteLine($"wrote Dialogue/{module}.json ({nodes.Count} nodes)");
}

