using UnityEngine.UI;

namespace EggRescue
{
    public sealed class PlayerInteraction : MonoBehaviour
    {
        [SerializeField] float rayDistance = 3.5f;
        [SerializeField] LayerMask mask = ~0;
        [SerializeField] Text promptText;

        Interactable _current;

        public void SetPromptLabel(Text label) { promptText = label; }

        void Update()
        {
            if (GameEvents.InputLocked)
            {
                SetCurrent(null);
                return;
            }

            Interactable hit = null;
            var ray = Camera.main != null
                ? Camera.main.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f))
                : new Ray(transform.position, transform.forward);
            RaycastHit info;
            if (Physics.Raycast(ray, out info, rayDistance, mask, QueryTriggerInteraction.Collide))
            {
                hit = info.collider.GetComponentInParent<Interactable>();
                if (hit != null && !hit.InteractionEnabled)
                    hit = null;
                if (hit != null && Vector3.Distance(transform.position, info.point) > hit.MaxDistance)
                    hit = null;
            }

            SetCurrent(hit);

            if (_current != null && (Input.GetKeyDown(KeyCode.E) || Input.GetMouseButtonDown(0)))
                _current.Interact();
        }

        void SetCurrent(Interactable next)
        {
            _current = next;
            if (promptText == null) return;
            if (next == null)
            {
                promptText.gameObject.SetActive(false);
            }
            else
            {
                promptText.gameObject.SetActive(true);
                promptText.text = string.IsNullOrEmpty(next.Prompt) ? "E 交互" : next.Prompt;
            }
        }
    }
}

