using UnityEngine;

namespace EggRescue
{
    public sealed class DialogueTrigger : MonoBehaviour
    {
        public string npcName;
        public int startId;

        Interactable _interactable;

        void Awake()
        {
            _interactable = GetComponent<Interactable>();
            if (_interactable == null) _interactable = gameObject.AddComponent<Interactable>();
            _interactable.OnInteract += StartDialogue;
        }

        void OnDestroy()
        {
            if (_interactable != null) _interactable.OnInteract -= StartDialogue;
        }

        public void StartDialogue()
        {
            InteractionPointVfx.DiscoverFrom(gameObject);
            if (!string.IsNullOrEmpty(npcName))
            {
                if (DialogueManager.Instance != null)
                    DialogueManager.Instance.StartNpc(npcName, startId);
                else
                    Debug.LogError("[DialogueTrigger] DialogueManager missing");
                return;
            }
            Debug.LogWarning("[DialogueTrigger] npcName empty on " + name);
        }

        public static bool StartNpcDialogue(string targetNpcName, int startId)
        {
            if (DialogueManager.Instance == null) return false;
            return DialogueManager.Instance.StartNpc(targetNpcName, startId);
        }
    }
}

using UnityEngine;

namespace EggRescue
{
    public sealed class DialogueAreaTrigger : MonoBehaviour
    {
        public string npcName;
        public int startNodeId = 1;
        public string requireVarName;
        public bool requireVarMustBe = true;
        public string blockVarName;
        public bool blockWhenTrue = true;
        public bool disableColliderAfterFire = true;
        public bool skipIfDialogueActive = true;

        bool _fired;
        bool _playerInside;

        void Update()
        {
            if (_fired || !_playerInside) return;
            TryFire();
        }

        void OnTriggerEnter(Collider other)
        {
            if (!InteractionUtil.IsLocalPlayer(other)) return;
            _playerInside = true;
            TryFire();
        }

        void OnTriggerExit(Collider other)
        {
            if (!InteractionUtil.IsLocalPlayer(other)) return;
            _playerInside = false;
        }

        void TryFire()
        {
            if (_fired) return;
            if (skipIfDialogueActive && GameEvents.DialogueActive) return;
            if (!ConditionsMet()) return;
            _fired = true;
            if (disableColliderAfterFire)
            {
                var col = GetComponent<Collider>();
                if (col != null) col.enabled = false;
            }
            DialogueTrigger.StartNpcDialogue(npcName, startNodeId);
        }

        bool ConditionsMet()
        {
            if (!string.IsNullOrEmpty(requireVarName))
            {
                if (GameState.GetBool(requireVarName) != requireVarMustBe)
                    return false;
            }
            if (!string.IsNullOrEmpty(blockVarName))
            {
                var blocked = GameState.GetBool(blockVarName);
                if (blockWhenTrue && blocked) return false;
                if (!blockWhenTrue && !blocked) return false;
            }
            return true;
        }
    }
}

