using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public sealed class MouseBrotherShop : MonoBehaviour
    {
        public static MouseBrotherShop Instance { get; private set; }

        const int HubId = 100;
        const int HubRevisitId = 95;
        const int NgPlusHubId = 910;

        static readonly int[] CheapIntel = { 0, 500, 510, 520, 530, 540, 550, 560, 570, 580, 590 };
        static readonly int[] PremiumIntel = { 0, 600, 610, 620, 630, 640, 650, 660, 670 };

        bool _refreshing;

        void Awake() { Instance = this; }

        void OnEnable() { GameEvents.MouseFlagsNeedRefresh += RefreshDerivedFlags; }
        void OnDisable() { GameEvents.MouseFlagsNeedRefresh -= RefreshDerivedFlags; }

        void Start() { RefreshDerivedFlags(); }

        void Update()
        {
            if (Time.frameCount % 120 == 0) RefreshDerivedFlags();
        }

        public static bool HandleAction(string action, DialogueOption option)
        {
            if (Instance != null) Instance.RefreshDerivedFlags();
            if (action == "cheap")
            {
                var node = PickCheap();
                if (!node.HasValue) { GoToHub(); return true; }
                if (!TrySpend(1)) { GoToHub(); return true; }
                if (Instance != null) Instance.RefreshDerivedFlags();
                Jump(node.Value);
                return true;
            }
            if (action == "premium")
            {
                var node = PickPremium();
                if (!node.HasValue) { GoToHub(); return true; }
                if (!TrySpend(5)) { GoToHub(); return true; }
                if (Instance != null) Instance.RefreshDerivedFlags();
                Jump(node.Value);
                return true;
            }
            if (action == "pay8_mint" || action == "pay8_frog")
            {
                if (!TrySpend(8))
                {
                    Jump(260);
                    return true;
                }
                GameState.SetBool("Mouse_MintFishPaid", true);
                GameState.SetBool("Mouse_PremiumPoolUnlocked", true);
                if (Instance != null) Instance.RefreshDerivedFlags();
                if (option != null && option.Next > 0) Jump(option.Next);
                else GoToHub();
                return true;
            }
            return false;
        }

        public static bool TrySpend(int amount)
        {
            var cur = GameState.GetInt("CheeseCount");
            if (cur < amount) return false;
            GameState.SetInt("CheeseCount", cur - amount);
            return true;
        }

        public void RefreshDerivedFlags()
        {
            if (_refreshing) return;
            _refreshing = true;
            GameState.SetBool("Mouse_CheapPoolAvailable", CheapAvailable());
            GameState.SetBool("Mouse_PremiumPoolAvailable", PremiumAvailable());
            GameState.SetBool("Mouse_CanAffordMint8InGame", CheeseRemainingTotal() >= 8);
            _refreshing = false;
        }

        static bool CheapAvailable()
        {
            for (var i = 1; i <= 10; i++)
                if (!Sold("Mouse_CheapSold_" + i.ToString("00"))) return true;
            return false;
        }

        static bool PremiumAvailable()
        {
            var limit = GameState.GetBool("Mouse_PremiumPoolUnlocked") ? 8 : 2;
            for (var i = 1; i <= limit; i++)
                if (!Sold("Mouse_PremiumSold_" + i.ToString("00"))) return true;
            return false;
        }

        static bool Sold(string name) { return GameState.GetBool(name); }

        static int? PickCheap()
        {
            var available = new List<int>();
            for (var i = 1; i <= 10; i++)
                if (!Sold("Mouse_CheapSold_" + i.ToString("00"))) available.Add(CheapIntel[i]);
            if (available.Count == 0) return null;
            return available[Random.Range(0, available.Count)];
        }

        static int? PickPremium()
        {
            var limit = GameState.GetBool("Mouse_PremiumPoolUnlocked") ? 8 : 2;
            var available = new List<int>();
            for (var i = 1; i <= limit; i++)
                if (!Sold("Mouse_PremiumSold_" + i.ToString("00"))) available.Add(PremiumIntel[i]);
            if (available.Count == 0) return null;
            return available[Random.Range(0, available.Count)];
        }

        static int CheeseRemainingTotal()
        {
            return GameState.GetInt("CheeseCount") + CheeseRegistry.UnpickedAmount(GameState.GetBool("NGPlus"));
        }

        static void GoToHub()
        {
            if (GameState.GetBool("NGPlus")) Jump(NgPlusHubId);
            else if (GameState.GetBool("Mouse_FirstGreetShown")) Jump(HubRevisitId);
            else Jump(HubId);
        }

        static void Jump(int nodeId)
        {
            if (DialogueManager.Instance != null)
                DialogueManager.Instance.JumpToNode(nodeId);
        }
    }
}

using UnityEngine;

namespace EggRescue
{
    public sealed class CheesePickup : MonoBehaviour
    {
        public string pickupId;
        public int amount = 1;
        public bool requiresNGPlus;
        public GameObject visualRoot;
        public GameObject pickupVfx;

        string Id
        {
            get
            {
                if (!string.IsNullOrEmpty(pickupId)) return pickupId;
                var parent = transform.parent;
                if (parent != null && parent.parent != null && parent.parent.name == "奶酪散点")
                    return parent.name;
                return gameObject.name;
            }
        }

        void Start()
        {
            CheeseRegistry.Register(Id, amount, requiresNGPlus);
            ApplyVisibility();
        }

        void OnDestroy()
        {
            CheeseRegistry.Unregister(Id);
        }

        void OnTriggerEnter(Collider other)
        {
            if (!InteractionUtil.IsLocalPlayer(other)) return;
            AudioDirector.PlayAudio("audio_cheese");
            TryPickup();
        }

        public void TryPickup()
        {
            if (CheeseRegistry.IsPicked(Id)) return;
            if (requiresNGPlus && !GameState.GetBool("NGPlus")) return;
            GameState.SetInt("CheeseCount", GameState.GetInt("CheeseCount") + amount);
            CheeseRegistry.MarkPicked(Id);
            PlayVfx();
            Hide(false);
        }

        public void ApplyVisibility()
        {
            var ngOk = !requiresNGPlus || GameState.GetBool("NGPlus");
            if (ngOk && !CheeseRegistry.IsPicked(Id)) Show();
            else Hide(true);
        }

        void Hide(bool hideVfx)
        {
            var vis = ResolveVisual();
            if (vis != null) vis.SetActive(false);
            var col = GetComponent<Collider>();
            if (col != null) col.enabled = false;
            if (hideVfx)
            {
                var vfx = ResolveVfx();
                if (vfx != null) vfx.SetActive(false);
            }
        }

        void Show()
        {
            var vis = ResolveVisual();
            if (vis != null) vis.SetActive(true);
            var col = GetComponent<Collider>();
            if (col != null) col.enabled = true;
            var vfx = ResolveVfx();
            if (vfx != null)
            {
                vfx.SetActive(true);
                var systems = vfx.GetComponentsInChildren<ParticleSystem>(true);
                var stop = ParticleSystemStopBehavior.StopEmittingAndClear;
                for (var i = 0; i < systems.Length; i++) systems[i].Stop(true, stop);
            }
        }

        void PlayVfx()
        {
            var vfx = ResolveVfx();
            if (vfx == null) return;
            vfx.SetActive(true);
            var systems = vfx.GetComponentsInChildren<ParticleSystem>(true);
            for (var i = 0; i < systems.Length; i++)
            {
                systems[i].Clear(true);
                systems[i].Play(true);
            }
        }

        GameObject ResolveVisual()
        {
            if (visualRoot != null) return visualRoot;
            var t = transform.Find("cheeseSingle");
            return t != null ? t.gameObject : null;
        }

        GameObject ResolveVfx()
        {
            if (pickupVfx != null) return pickupVfx;
            var t = transform.Find("vfx_interact");
            return t != null ? t.gameObject : null;
        }
    }
}

using UnityEngine;

namespace EggRescue
{
    public sealed class CheeseSpawner : MonoBehaviour
    {
        public GameObject cheesePrefab;
        const string ChildName = "Pickup";
        public static CheeseSpawner Instance { get; private set; }

        void Awake() { Instance = this; }

        void Start() { SpawnAll(); }

        public void SpawnAll()
        {
            if (cheesePrefab == null)
            {
                Debug.LogWarning("[CheeseSpawner] prefab missing");
                return;
            }
            for (var i = 0; i < transform.childCount; i++)
                EnsureMarker(transform.GetChild(i));
        }

        void EnsureMarker(Transform marker)
        {
            var existing = marker.Find(ChildName);
            if (existing != null)
            {
                var pickup = existing.GetComponent<CheesePickup>();
                if (pickup != null) pickup.ApplyVisibility();
                return;
            }
            if (CheeseRegistry.IsPicked(marker.name)) return;
            var go = Instantiate(cheesePrefab, marker);
            go.name = ChildName;
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one;
        }
    }
}

using UnityEngine;

namespace EggRescue
{
    public sealed class CheeseRefreshManager : MonoBehaviour
    {
        void OnEnable() { GameEvents.NGPlusActivated += RefreshAll; }
        void OnDisable() { GameEvents.NGPlusActivated -= RefreshAll; }

        void Start()
        {
            if (GameState.GetBool("NGPlus")) RefreshAll();
        }

        void RefreshAll()
        {
            CheeseRegistry.ClearPicked();
            if (CheeseSpawner.Instance != null) CheeseSpawner.Instance.SpawnAll();
            var pickups = FindObjectsOfType<CheesePickup>(true);
            for (var i = 0; i < pickups.Length; i++) pickups[i].ApplyVisibility();
        }
    }
