        }

        void Add(string id, GameObject go, string cond)
        {
            _entries[id] = new EntryDef { Go = go, Cond = cond };
        }

        void AddIntel(string key, string tier, string text)
        {
            _intelTier[key] = tier;
            _intelText[key] = text;
        }

        void CheckAllEntries()
        {
            foreach (var kv in _entries)
            {
                bool unlocked;
                _unlocked.TryGetValue(kv.Key, out unlocked);
                if (kv.Value.Go != null && !unlocked && ConditionEvaluator.EvalUnlockString(kv.Value.Cond))
                    Unlock(kv.Key);
            }
            Reconcile();
        }

        void Unlock(string id)
        {
            EntryDef def;
            if (!_entries.TryGetValue(id, out def) || def.Go == null) return;
            bool already;
            if (_unlocked.TryGetValue(id, out already) && already) return;
            _unlocked[id] = true;
            def.Go.SetActive(true);
            QueueReveal(id, def.Go);
            if (id == "E10")
            {
                _page = 2;
                if (IsOpen()) { HidePages(); ShowPage(); }
            }
            Reconcile();
        }

        void Reconcile()
        {
            foreach (var link in _links)
            {
                if (IsUnlocked(link.A) && IsUnlocked(link.B))
                {
                    if (link.Gos != null) SetGos(link.Gos, true);
                    else if (link.Go != null) link.Go.SetActive(true);
                }
            }
            foreach (var mod in _mods)
            {
                if (mod.Go == null) continue;
                var show = (!string.IsNullOrEmpty(mod.EntryUnlock) && IsUnlocked(mod.EntryUnlock))
                           || (!string.IsNullOrEmpty(mod.Cond) && ConditionEvaluator.EvalUnlockString(mod.Cond));
                if (show) mod.Go.SetActive(true);
            }
        }

        bool IsUnlocked(string id)
        {
            bool v;
            return _unlocked.TryGetValue(id, out v) && v;
        }

        void QueueReveal(string id, GameObject go)
        {
            if (go == null || _pending.ContainsKey(id) || _anims.ContainsKey(id)) return;
            var cg = GetGroup(go);
            cg.alpha = 0f;
            var page = ResolvePage(go);
            if (page <= 0) { cg.alpha = 1f; return; }
            _pending[id] = new Pending { Group = cg, Page = page };
            RevealIcon();
            AudioDirector.PlayAudio("audio_unlockClue");
            if (!IsOpen()) PlayIconBounce();
            else TryStartPending();
            UpdatePageDots();
        }

        void TryStartPending()
        {
            if (!IsOpen()) return;
            var started = new List<string>();
            foreach (var kv in _pending)
            {
                if (kv.Value.Page != _page || kv.Value.Group == null) continue;
                _anims[kv.Key] = new Anim { Group = kv.Value.Group, Phase = "fade", Elapsed = 0f };
                kv.Value.Group.alpha = 0f;
                started.Add(kv.Key);
            }
            for (var i = 0; i < started.Count; i++) _pending.Remove(started[i]);
            if (started.Count > 0)
            {
                AudioDirector.PlayAudio("audio_showClue");
                UpdatePageDots();
            }
        }

        void SpawnIntel(string varName, bool fade)
        {
            if (_intelSpawned.ContainsKey(varName)) return;
            if (!ConditionEvaluator.EvalUnlockString(varName + "==true")) return;
            string tier;
            if (!_intelTier.TryGetValue(varName, out tier)) return;
            var prefab = tier == "premium" ? intelPremiumPrefab : intelCheapPrefab;
            if (prefab == null) return;
            Transform parent = null;
            var maxLeft = intelLeftColumnMax <= 0 ? 9 : intelLeftColumnMax;
            if (intelLayoutLeft != null && intelLayoutLeft.transform.childCount < maxLeft)
                parent = intelLayoutLeft.transform;
            else if (intelLayoutRight != null) parent = intelLayoutRight.transform;
            else if (intelLayoutLeft != null) parent = intelLayoutLeft.transform;
            if (parent == null) return;
            var instance = Instantiate(prefab, parent);
            instance.SetActive(true);
            var label = instance.GetComponentInChildren<Text>(true);
            string text;
            if (label != null && _intelText.TryGetValue(varName, out text)) label.text = text;
            if (fade) QueueReveal("intel_" + varName, instance);
            else GetGroup(instance).alpha = 1f;
            _intelSpawned[varName] = instance;
        }

        void RebuildIntel()
        {
            ClearLayout(intelLayoutLeft);
            ClearLayout(intelLayoutRight);
            _intelSpawned.Clear();
            for (var i = 0; i < IntelOrder.Length; i++)
            {
                if (ConditionEvaluator.EvalUnlockString(IntelOrder[i] + "==true"))
                    SpawnIntel(IntelOrder[i], false);
            }
        }

        static void ClearLayout(GameObject layout)
        {
            if (layout == null) return;
            for (var i = layout.transform.childCount - 1; i >= 0; i--)
                Destroy(layout.transform.GetChild(i).gameObject);
        }

        void OnOpenClick()
        {
            if (GameEvents.DialogueActive || IsOpen()) return;
            AudioDirector.PlayAudio("audio_openNote");
            HideHud();
            boolPanel.SetActive(true);
            if (close != null) close.gameObject.SetActive(true);
            GameEvents.RaiseNotebookOpened();
            UpdateRedDot();
            CheckAllEntries();
            HidePages();
            ShowPage();
        }

        void OnCloseClick()
        {
            AudioDirector.PlayAudio("audio_closeNote");
            boolPanel.SetActive(false);
            RestoreHud();
            if (_iconVisible && open != null) open.gameObject.SetActive(true);
            if (close != null) close.gameObject.SetActive(false);
            _lastOpenInteractable = null;
            GameEvents.RaiseNotebookClosed();
            RefreshOpenInteractable();
            UpdateRedDot();
        }

        void GoToPage(int page)
        {
            if (pageContents == null || page < 1 || page > pageContents.Length || page == _page) return;
            AudioDirector.PlayAudio("audio_switchPage");
            _page = page;
            HidePages();
            ShowPage();
        }

        void HidePages()
        {
            if (pageContents == null) return;
            for (var i = 0; i < pageContents.Length; i++)
                if (pageContents[i] != null) pageContents[i].SetActive(false);
        }

        void ShowPage()
        {
            if (pageContents == null || pageContents.Length == 0) return;
            var idx = _page - 1;
            if (idx >= 0 && idx < pageContents.Length && pageContents[idx] != null)
                pageContents[idx].SetActive(true);
            TryStartPending();
        }

        bool IsOpen() { return boolPanel != null && boolPanel.activeSelf; }

        void BindTabs(Button[] tabs, int fromPage)
        {
            if (tabs == null) return;
            for (var i = 0; i < tabs.Length; i++)
            {
                var target = i + 1;
                if (tabs[i] != null && target != fromPage)
                    tabs[i].onClick.AddListener(() => GoToPage(target));
            }
        }

        void CollectDots()
        {
            Collect(page1TabBtns);
            Collect(page2TabBtns);
            Collect(page3TabBtns);
            Collect(page4TabBtns);
        }

        void Collect(Button[] tabs)
        {
            if (tabs == null) return;
            for (var i = 0; i < tabs.Length; i++)
            {
                if (tabs[i] == null) continue;
                var dot = tabs[i].transform.Find("Dot");
                if (dot == null) continue;
                var page = i + 1;
                List<GameObject> list;
                if (!_pageDots.TryGetValue(page, out list))
                {
                    list = new List<GameObject>();
                    _pageDots[page] = list;
                }
                list.Add(dot.gameObject);
                dot.gameObject.SetActive(false);
            }
        }

        void UpdatePageDots()
        {
            for (var page = 1; page <= 4; page++)
            {
                List<GameObject> dots;
                if (!_pageDots.TryGetValue(page, out dots)) continue;
                var show = PageHasPending(page);
                for (var i = 0; i < dots.Count; i++)
                    if (dots[i] != null) dots[i].SetActive(show);
            }
            UpdateRedDot();
        }

        bool PageHasPending(int page)
        {
            foreach (var kv in _pending)
                if (kv.Value.Page == page) return true;
            return false;
        }

        bool HasPending()
        {
            return _pending.Count > 0;
        }

        void UpdateRedDot()
        {
            var show = HasPending() && !IsOpen();
            if (openRedDot != null) openRedDot.SetActive(show);
            if (show && !_lastRedDot) PlayIconBounce();
            _lastRedDot = show;
        }

        void RefreshOpenInteractable()
        {
            if (open == null) return;
            var can = !GameEvents.DialogueActive;
            if (_lastOpenInteractable == can) return;
            _lastOpenInteractable = can;
            open.interactable = can;
        }

        void RevealIcon()
        {
            if (_iconVisible || open == null) return;
            _iconVisible = true;
            open.gameObject.SetActive(true);
            _lastOpenInteractable = null;
            RefreshOpenInteractable();
        }

        void ResolveIcon()
        {
            if (_openIcon != null || open == null) return;
            var t = open.transform.Find("NoteImage");
            if (t == null) return;
            _openIcon = t;
            _iconBase = t.localScale;
        }

        void PlayIconBounce()
        {
            ResolveIcon();
            if (_openIcon == null) return;
            _iconBounce = true;
            _iconElapsed = 0f;
        }

        void TickIcon(float dt)
        {
            if (!_iconBounce) return;
            ResolveIcon();
            if (_openIcon == null) { _iconBounce = false; return; }
            _iconElapsed += dt;
            var p = _iconElapsed / IconBounceDuration;
            if (p >= 1f)
            {
                _openIcon.localScale = _iconBase;
                _iconBounce = false;
                return;
            }
            var s = 1f + (IconBouncePeak - 1f) * Mathf.Sin(p * Mathf.PI);
            _openIcon.localScale = _iconBase * s;
        }

        int ResolvePage(GameObject go)
        {
            if (go == null || pageContents == null) return 0;
            var t = go.transform;
            for (var i = 0; i < pageContents.Length; i++)
            {
                if (pageContents[i] != null && t.IsChildOf(pageContents[i].transform))
                    return i + 1;
            }
            return 0;
        }

        static CanvasGroup GetGroup(GameObject go)
        {
            var cg = go.GetComponent<CanvasGroup>();
            if (cg == null) cg = go.AddComponent<CanvasGroup>();
            return cg;
        }

        static void SetGos(GameObject[] gos, bool on)
        {
            if (gos == null) return;
            for (var i = 0; i < gos.Length; i++)
                if (gos[i] != null) gos[i].SetActive(on);
        }

        void HideHud()
        {
            _hiddenHud = new List<HudState>();
            if (hideOnOpen == null) return;
            for (var i = 0; i < hideOnOpen.Length; i++)
            {
                var go = hideOnOpen[i];
                if (go == null) continue;
                _hiddenHud.Add(new HudState { Go = go, WasActive = go.activeSelf });
                go.SetActive(false);
            }
        }

        void RestoreHud()
        {
            if (_hiddenHud == null) return;
            for (var i = 0; i < _hiddenHud.Count; i++)
                if (_hiddenHud[i].Go != null) _hiddenHud[i].Go.SetActive(_hiddenHud[i].WasActive);
            _hiddenHud = null;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

namespace EggRescue
{
    public sealed class EndingController : MonoBehaviour
    {
        public GameObject[] panels;
        public Button clickArea;
        public float fadeDuration = 1f;
        public GameObject[] hideOnEnding;

        string _phase = "idle";
        float _elapsed;
        string _fadeKind;
        int _panelIndex;
        bool _finalized;
        bool _bgLocked;
        Image _bg;
        bool _advanceBound;
        GameObject _crossFrom;
        GameObject _crossTo;
        GameObject _fadeInTarget;
        GameObject _fadeOutPanel;
        float _preRemain;
        struct HudState { public GameObject Go; public bool WasActive; }
        HudState[] _hidden;

        const float PreFallback = 2f;

        void Start()
        {
            BindClick();
            if (_phase == "idle") EnsureHidden();
        }

        public void StartEnding()
        {
            if (_phase != "idle" && _phase != "done") return;
            _finalized = false;
            _panelIndex = 0;
            _fadeKind = null;
            _fadeInTarget = null;
            _fadeOutPanel = null;
            _crossFrom = null;
            _crossTo = null;
            _preRemain = 0f;
            _phase = "fadeBg";
            BindClick();
            HidePanels();
            SetClick(false);
            HideHud();
            _bgLocked = false;
            SetRaycast(true);
            AudioDirector.StopBGM();
            AudioDirector.PlayAudio("audio_preEnding");
            var len = AudioDirector.GetClipLength("audio_preEnding");
            if (len <= 0f) len = PreFallback;
            _preRemain = len;
            gameObject.SetActive(true);
            SetBg(0f);
            _fadeKind = "bg";
            _elapsed = 0f;
        }

        void Update()
        {
            var dt = Time.deltaTime;
            if ((_phase == "fadeBg" || _phase == "waitPreEnding") && _preRemain > 0f)
            {
                _preRemain -= dt;
                if (_preRemain < 0f) _preRemain = 0f;
            }
            if (_phase == "waitPreEnding")
            {
                if (_preRemain <= 0f) BeginFirst();
                return;
            }
            if (string.IsNullOrEmpty(_fadeKind)) return;
            var duration = fadeDuration <= 0f ? 1f : fadeDuration;
            _elapsed += dt;
            var p = Mathf.Clamp01(_elapsed / duration);
            var eased = p * p * (3f - 2f * p);
            if (_fadeKind == "bg") SetBg(eased);
            else if (_fadeKind == "in") SetVisual(_fadeInTarget, eased);
            else if (_fadeKind == "crossfade")
            {
                SetVisual(_crossFrom, 1f - eased);
                SetVisual(_crossTo, eased);
            }
            else if (_fadeKind == "outPanel") SetVisual(_fadeOutPanel, 1f - eased);
            else if (_fadeKind == "fadeOutBg") SetBg(1f - eased);
            if (p >= 1f)
            {
                _fadeKind = null;
                OnFadeComplete();
            }
        }

        void OnFadeComplete()
        {
            if (_phase == "fadeBg")
            {
                LockBg();
                if (_preRemain > 0f) _phase = "waitPreEnding";
                else BeginFirst();
                return;
            }
            if (_phase == "fadeIn")
            {
                SetVisual(_fadeInTarget, 1f);
                _fadeInTarget = null;
                if (PanelCount() == 0) HoldBlack();
                else { _phase = "waitClick"; SetClick(true); }
                return;
            }
            if (_phase == "crossfade")
            {
                if (_crossFrom != null) _crossFrom.SetActive(false);
                SetVisual(_crossTo, 1f);
                _crossFrom = null;
                _crossTo = null;
                _phase = "waitClick";
                SetClick(true);
                return;
            }
            if (_phase == "fadeOutPanel")
            {
                if (_fadeOutPanel != null) _fadeOutPanel.SetActive(false);
                _fadeOutPanel = null;
                HoldBlack();
                return;
            }
            if (_phase == "fadeOutBg")
            {
                SetBg(0f);
                Finish();
            }
        }

        void BeginFirst()
        {
            LockBg();
            AudioDirector.PlayMusic("audio_endingLoop");
            _panelIndex = 1;
            var go = panels != null && panels.Length > 0 ? panels[0] : null;
            if (go != null)
            {
                _phase = "fadeIn";
                _fadeInTarget = go;
                go.SetActive(true);
                SetVisual(go, 0f);
                _fadeKind = "in";
                _elapsed = 0f;
            }
            else HoldBlack();
        }

        void HoldBlack()
        {
            _phase = "holdBlack";
            LockBg();
            GameState.SetBool("NGPlus", true);
            if (LevelTeleport.Instance != null) LevelTeleport.Instance.ResetPosition();
            else
            {
                var spawn = GameObject.Find("PlayerSpawn");
                if (spawn != null) LevelTeleport.TeleportTo(spawn.transform);
            }
            _phase = "fadeOutBg";
            _bgLocked = false;
            SetClick(false);
            SetBg(1f);
            _fadeKind = "fadeOutBg";
            _elapsed = 0f;
        }

        void Finish()
        {
            if (_finalized) return;
            _finalized = true;
            _phase = "done";
            SetClick(false);
            SetRaycast(false);
            AudioDirector.StopBGM();
            AudioDirector.PlayBGM();
            RestoreHud();
            gameObject.SetActive(false);
        }

        void OnAdvance()
        {
            if (_phase != "waitClick") return;
            GameObject prev = null;
            if (panels != null && _panelIndex >= 1 && _panelIndex <= panels.Length)
                prev = panels[_panelIndex - 1];
            _panelIndex++;
            if (_panelIndex <= PanelCount())
            {
                var next = panels[_panelIndex - 1];
                _phase = "crossfade";
                _crossFrom = prev;
                _crossTo = next;
                SetClick(false);
                if (next != null) { next.SetActive(true); SetVisual(next, 0f); }
                SetVisual(prev, 1f);
                _fadeKind = "crossfade";
                _elapsed = 0f;
            }
            else
            {
                _phase = "fadeOutPanel";
                _fadeOutPanel = prev;
                LockBg();
                SetClick(false);
                _fadeKind = "outPanel";
                _elapsed = 0f;
            }
        }

        void BindClick()
        {
            if (_advanceBound) return;
            _advanceBound = true;
            if (clickArea != null)
            {
                clickArea.onClick.AddListener(OnAdvance);
                return;
            }
            var btn = GetComponent<Button>();
            if (btn == null) btn = gameObject.AddComponent<Button>();
            btn.onClick.AddListener(OnAdvance);
            clickArea = btn;
        }

        int PanelCount() { return panels == null ? 0 : panels.Length; }

        void HidePanels()
        {
            if (panels == null) return;
            for (var i = 0; i < panels.Length; i++)
                if (panels[i] != null) panels[i].SetActive(false);
        }

        void EnsureHidden()
        {
            HidePanels();
            SetBg(0f);
            gameObject.SetActive(false);
        }

        Image Bg()
        {
            if (_bg == null) _bg = GetComponent<Image>();
            return _bg;
        }

        void SetBg(float a)
        {
            if (_bgLocked && a < 1f) return;
            var img = Bg();
            if (img == null) return;
            var c = img.color;
            c.a = a;
            img.color = c;
        }

        void LockBg()
        {
            _bgLocked = true;
            SetBg(1f);
        }

        static void SetVisual(GameObject go, float a)
        {
            if (go == null) return;
            var img = go.GetComponent<Image>();
            if (img != null)
            {
                var c = img.color;
                c.a = a;
                img.color = c;
                return;
            }
            var txt = go.GetComponent<Text>();
            if (txt != null)
            {
                var c = txt.color;
                c.a = a;
                txt.color = c;
            }
        }

        void SetClick(bool on)
        {
            if (clickArea != null) clickArea.interactable = on;
        }

        void SetRaycast(bool on)
        {
            var img = Bg();
            if (img != null) img.raycastTarget = on;
        }

        void HideHud()
        {
            if (hideOnEnding == null) return;
            _hidden = new HudState[hideOnEnding.Length];
            for (var i = 0; i < hideOnEnding.Length; i++)
            {
                var go = hideOnEnding[i];
                if (go == null) continue;
                _hidden[i] = new HudState { Go = go, WasActive = go.activeSelf };
                go.SetActive(false);
            }
        }

        void RestoreHud()
        {
            if (_hidden == null) return;
            for (var i = 0; i < _hidden.Length; i++)
                if (_hidden[i].Go != null) _hidden[i].Go.SetActive(_hidden[i].WasActive);
            _hidden = null;
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

namespace EggRescue
{
    public sealed class GameBootstrap : MonoBehaviour
    {
        public static GameBootstrap Instance { get; private set; }
        public Transform playerSpawn;
        public GameObject playerPrefab;
        bool _booted;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void AutoBoot()
        {
            if (FindObjectOfType<GameBootstrap>() != null) return;
            var go = new GameObject("EggRescue_Runtime");
            go.AddComponent<GameBootstrap>();
        }

        void Awake()
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
            Boot();
        }

        public void Boot()
        {
            if (_booted) return;
            _booted = true;
            GameState.LoadDefaults();
            NpcRegistry.Load();
            DialogueDatabase.LoadAll();
            if (SaveService.Load()) { }
            EnsureAudio();
            EnsureDialogue();
            EnsurePlayer();
            EnsureSystems();
            AutoWireWorld();
        }

        void EnsureAudio()
        {
            if (AudioDirector.Instance != null) return;
            gameObject.AddComponent<AudioDirector>();
        }

        void EnsureDialogue()
        {
            if (DialogueManager.Instance != null) return;
            var existing = GameObject.Find("DialogueManager");
            if (existing != null)
            {
                var dm = existing.GetComponent<DialogueManager>();
                if (dm == null) existing.AddComponent<DialogueManager>();
                return;
            }
            var go = new GameObject("DialogueManager");
            go.AddComponent<DialogueManager>();
        }

        void EnsurePlayer()
        {
            if (PlayerController.Instance != null) return;
            Vector3 pos;
            Quaternion rot;
            ResolveSpawn(out pos, out rot);
            GameObject player;
            if (playerPrefab != null)
            {
                player = Instantiate(playerPrefab, pos, rot);
            }
            else
            {
                player = GameObject.CreatePrimitive(PrimitiveType.Capsule);
                player.name = "Player";
                var col = player.GetComponent<Collider>();
                if (col != null) Destroy(col);
                var cc = player.AddComponent<CharacterController>();
                cc.height = 1.8f;
                cc.radius = 0.4f;
                cc.center = new Vector3(0f, 0.9f, 0f);
                player.transform.SetPositionAndRotation(pos, rot);
            }
            if (player.GetComponent<PlayerController>() == null)
