        void AutoWireWorld()
        {
            WireNpc("淑芬", "淑芬", 0);
            WireNpc("大黄", "大黄", 0);
            WireNpc("大黄 2", "大黄", 0);
            WireNpc("黑猫", "黑猫", 0);
            WireNpc("悲伤蛙", "悲伤蛙", 0);
