            WireNpc("小鸡侦探团", "小鸡侦探团", 0);
            WireNpc("闪电蜗牛", "闪电蜗牛", 0);
            WireNpc("老鼠兄弟", "老鼠兄弟", 0);
            WireNpc("大树", "大树", 0);
            AddIfMissing<DaHuangController>(GameObject.Find("大黄"));
            AddIfMissing<DaHuangController>(GameObject.Find("大黄 2"));
            AddIfMissing<ShuFenController>(FindNamedContains("淑芬") != null && GameObject.Find("淑芬") != null
                ? (GameObject.Find("淑芬").transform.parent != null ? GameObject.Find("淑芬").transform.parent.gameObject : GameObject.Find("淑芬"))
                : null);
            AddIfMissing<BlackCatInteractionController>(GameObject.Find("黑猫"));
            AddIfMissing<CrowInteractionController>(GameObject.Find("乌鸦"));
            AddIfMissing<E03EavesdropController>(FindNamedContains("E03"));
            AddIfMissing<E06LadderController>(FindNamedContains("E06"));
            AddIfMissing<ComicGateTrigger>(FindNamedContains("E20"));
            var tree = FindNamedContains("TreeDialogue");
