using UnityEngine;

namespace EggRescue
{
    public sealed class CheeseSpawner : MonoBehaviour
    {
        public GameObject cheesePrefab;
        const string ChildName = "Pickup";
        public static CheeseSpawner Instance { get; private set; }

        void Awake() { Instance = this; }

        void Start()
        {
            ResolvePrefab();
            SpawnAll();
        }

        public void SpawnAll()
        {
            ResolvePrefab();
            if (cheesePrefab == null)
            {
                Debug.LogWarning("[CheeseSpawner] prefab missing");
                return;
            }
            for (var i = 0; i < transform.childCount; i++)
                EnsureMarker(transform.GetChild(i));
        }

        void ResolvePrefab()
        {
            if (cheesePrefab != null) return;
            cheesePrefab = Resources.Load<GameObject>("CheesePickup");
#if UNITY_EDITOR
            if (cheesePrefab == null)
                cheesePrefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/CheesePickup.prefab");
#endif
        }

        void EnsureMarker(Transform marker)
        {
            var existing = marker.Find(ChildName);
            if (existing != null)
            {
                WirePickup(existing.gameObject, marker.name);
                return;
            }
            if (CheeseRegistry.IsPicked(marker.name)) return;
            var go = Instantiate(cheesePrefab, marker);
            go.name = ChildName;
            go.transform.localPosition = Vector3.zero;
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one;
            WirePickup(go, marker.name);
        }

        static void WirePickup(GameObject go, string markerName)
        {
            if (go == null) return;
            DisableDouyin(go);
            var pickup = go.GetComponent<CheesePickup>();
            if (pickup == null) pickup = go.AddComponent<CheesePickup>();
            if (string.IsNullOrEmpty(pickup.pickupId))
                pickup.pickupId = markerName;
            if (markerName != null && markerName.StartsWith("C02"))
                pickup.requiresNGPlus = true;
            pickup.EnsureTrigger();
            pickup.ApplyVisibility();
        }

        static void DisableDouyin(GameObject go)
        {
            var behaviours = go.GetComponentsInChildren<MonoBehaviour>(true);
            for (var i = 0; i < behaviours.Length; i++)
            {
                var mb = behaviours[i];
                if (mb != null && mb.GetType().Name == "DouyinScript")
                    mb.enabled = false;
            }
        }
    }
}

using UnityEngine;

namespace EggRescue
{
    public sealed class CheesePickup : MonoBehaviour
    {
        public string pickupId;
        public int amount = 1;
        public bool requiresNGPlus;
        public GameObject visualRoot;
        public GameObject pickupVfx;

        bool _pickedThisSession;

        string Id
        {
            get
            {
                if (!string.IsNullOrEmpty(pickupId)) return pickupId;
                var parent = transform.parent;
                if (parent != null && parent.parent != null && parent.parent.name == "奶酪散点")
                    return parent.name;
                return gameObject.name;
            }
        }

        void Awake()
        {
            EnsureTrigger();
        }

        void Start()
        {
            CheeseRegistry.Register(Id, amount, requiresNGPlus);
            ApplyVisibility();
        }

        void OnDestroy()
        {
            CheeseRegistry.Unregister(Id);
        }

        void OnTriggerEnter(Collider other)
        {
            if (!InteractionUtil.IsLocalPlayer(other)) return;
            TryPickup();
        }

        void OnTriggerStay(Collider other)
        {
            if (!InteractionUtil.IsLocalPlayer(other)) return;
            TryPickup();
        }

        void LateUpdate()
        {
            if (_pickedThisSession || CheeseRegistry.IsPicked(Id)) return;
            var player = PlayerController.Instance;
            if (player == null) return;
            var cc = player.GetComponent<CharacterController>();
            var col = ResolveCollider();
            if (cc == null || col == null || !col.enabled) return;
            if (col.bounds.Intersects(cc.bounds))
                TryPickup();
        }

        public void EnsureTrigger()
        {
            var col = ResolveCollider();
            if (col == null)
            {
                var box = gameObject.AddComponent<BoxCollider>();
                box.size = new Vector3(0.8f, 0.8f, 0.8f);
                box.center = new Vector3(0f, 0.4f, 0f);
                col = box;
            }
            col.isTrigger = true;
            col.enabled = true;
        }

        public void TryPickup()
        {
            if (_pickedThisSession || CheeseRegistry.IsPicked(Id)) return;
            if (requiresNGPlus && !GameState.GetBool("NGPlus")) return;
            _pickedThisSession = true;
            GameState.SetInt("CheeseCount", GameState.GetInt("CheeseCount") + amount);
            CheeseRegistry.MarkPicked(Id);
            AudioDirector.PlayAudio("audio_cheese");
            PlayVfx();
            Hide(false);
        }

        public void ApplyVisibility()
        {
            var ngOk = !requiresNGPlus || GameState.GetBool("NGPlus");
            if (ngOk && !CheeseRegistry.IsPicked(Id))
            {
                _pickedThisSession = false;
                Show();
            }
            else Hide(true);
        }

        void Hide(bool hideVfx)
        {
            var vis = ResolveVisual();
            if (vis != null) vis.SetActive(false);
            var col = ResolveCollider();
            if (col != null) col.enabled = false;
            if (hideVfx)
            {
                var vfx = ResolveVfx();
                if (vfx != null) vfx.SetActive(false);
            }
        }

        void Show()
        {
            var vis = ResolveVisual();
            if (vis != null) vis.SetActive(true);
            EnsureTrigger();
            var vfx = ResolveVfx();
            if (vfx != null)
            {
                vfx.SetActive(true);
                var systems = vfx.GetComponentsInChildren<ParticleSystem>(true);
                var stop = ParticleSystemStopBehavior.StopEmittingAndClear;
                for (var i = 0; i < systems.Length; i++) systems[i].Stop(true, stop);
            }
        }

        void PlayVfx()
        {
            var vfx = ResolveVfx();
            if (vfx == null) return;
            vfx.SetActive(true);
            var systems = vfx.GetComponentsInChildren<ParticleSystem>(true);
            for (var i = 0; i < systems.Length; i++)
            {
                systems[i].Clear(true);
                systems[i].Play(true);
            }
        }

        Collider ResolveCollider()
        {
            var col = GetComponent<Collider>();
            if (col != null) return col;
            return GetComponentInChildren<Collider>(true);
        }

        GameObject ResolveVisual()
        {
            if (visualRoot != null) return visualRoot;
            var t = transform.Find("cheeseSingle");
            if (t == null) t = transform.Find("Visual");
            return t != null ? t.gameObject : null;
        }

        GameObject ResolveVfx()
        {
            if (pickupVfx != null) return pickupVfx;
            var t = transform.Find("vfx_interact");
            return t != null ? t.gameObject : null;
        }
    }
}

